<?php

namespace Overlook\Foundation\Http\Middleware;

use Closure;
use Illuminate\Http\Request;
use Overlook\Foundation\Review\WidgetMarkup;
use Symfony\Component\HttpFoundation\BinaryFileResponse;
use Symfony\Component\HttpFoundation\Response;
use Symfony\Component\HttpFoundation\StreamedResponse;

/**
 * Puts the review widget on the page.
 *
 * Injected into the response rather than offered as a Blade component the
 * layout includes, because there is no layout this package can rely on. Sites
 * are generated by whatever the Laravel installer ships that day, across five
 * starter kits, and the studio never edits the result — so a tag that has to be
 * placed by hand reaches the next project and none of the forty already built.
 * That is the same drift the template this package replaced died of.
 *
 * The cost is honest: a developer reading the layout sees nothing that explains
 * the script. It is the lesser cost, since there is no studio-owned layout for
 * them to read in the first place.
 */
class InjectReviewWidget
{
    public function handle(Request $request, Closure $next): Response
    {
        $response = $next($request);

        $key = config('foundation.review.key');

        /** The ordinary case on every production site: nothing to inject. */
        if (! config('foundation.review.enabled') || ! is_string($key) || $key === '') {
            return $response;
        }

        /** Neither holds a body this can rewrite without buffering the whole thing. */
        if ($response instanceof StreamedResponse || $response instanceof BinaryFileResponse) {
            return $response;
        }

        if (! str_contains((string) $response->headers->get('Content-Type'), 'text/html')) {
            return $response;
        }

        $content = $response->getContent();

        if (! is_string($content)) {
            return $response;
        }

        /**
         * The last closing body tag, not the first. A page that shows escaped
         * markup — a docs page, a mail preview, anything rendering a snippet —
         * contains an earlier one that is not the end of the document, and
         * str_replace would put the widget inside it.
         */
        $position = strripos($content, '</body>');

        if ($position === false) {
            return $response;
        }

        $content = substr($content, 0, $position).WidgetMarkup::for($key).substr($content, $position);

        /**
         * What the response was rendered from, which setContent overwrites with
         * the string it is given. Nothing serving the page cares, but every
         * assertion about it does: assertViewIs, assertViewHas and Inertia's
         * assertInertia all read the view back off the response, and against a
         * string they report the page is not a view at all. Left alone, this
         * middleware fails the test suite of every application it is installed
         * in — for a difference the browser never sees.
         */
        $original = $response->original;

        $response->setContent($content);

        $response->original = $original;

        /**
         * setContent leaves any Content-Length the response already declared,
         * which is now short by exactly the widget — and a browser handed a
         * truncated document renders a blank page.
         */
        if ($response->headers->has('Content-Length')) {
            $response->headers->set('Content-Length', (string) strlen($content));
        }

        return $response;
    }
}
